ValidationRule.errorConditionFormula:
$Profile.Name<>'Automated Process' && $Profile.Name<>'System Administrator' && $Profile.Name<>'Global Delegated Admin' &&
DAY(Effective_Date__c) <> 1
/*((!ISPICKVAL( Type__c , "Loss") && DAY(Effective_Date__c) <> 1) || (ISPICKVAL( Type__c , "Loss") && Effective_Date__c <> DATE( YEAR(Effective_Date__c), MONTH(Effective_Date__c), CASE( MONTH(Effective_Date__c), 1, 31, 2, IF(MOD(YEAR(Effective_Date__c), 4) = 0 && (MOD(YEAR(Effective_Date__c), 100) <> 0 || MOD(YEAR(Effective_Date__c), 400) = 0), 29, 28), 3, 31, 4, 30, 5, 31, 6, 30, 7, 31, 8, 31, 9, 30, 10, 31, 11, 30, 12, 31, 31 ) ))) */
/* La date d'effet doit être le premier jour d'un mois pour les prises, avenants et renouvellements. La date doit être le dernier jour du mois pour les pertes. */
